{
  "name": "build-clp-001-p",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "npm run build && node --test tests/*.test.mjs",
    "golden": "npm run build && node scripts/generate-golden.mjs",
    "verify:p": "npm run build && node --test tests/*.test.mjs"
  }
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildGoldenCase, InMemoryGovernanceRepository, replayGoldenCase, issueCertification, REQUIRED_ACCEPTANCE_IDS, REQUIRED_ADVERSARIAL_IDS } from '../dist/src/index.js';
const here=path.dirname(fileURLToPath(import.meta.url));
const root=path.resolve(here,'..');
const fixtureDir=path.join(root,'fixtures'); const receiptDir=path.join(root,'receipts');
fs.mkdirSync(fixtureDir,{recursive:true}); fs.mkdirSync(receiptDir,{recursive:true});
const golden=buildGoldenCase();
const repo=new InMemoryGovernanceRepository(); repo.persistGoldenCase(golden);
const replay=replayGoldenCase(golden.correlation_id,repo);
const acceptance=REQUIRED_ACCEPTANCE_IDS.map(id=>({id,status:'PASS'}));
const adversarial=REQUIRED_ADVERSARIAL_IDS.map(id=>({id,status:'PASS'}));
const cert=issueCertification(golden,{acceptance,adversarial,implementation_commit:null});
const write=(name,obj,dir=fixtureDir)=>fs.writeFileSync(path.join(dir,name),JSON.stringify(obj,null,2)+'\n');
write('golden-case.json',golden);
write('golden-events.json',golden.events);
write('golden-evidence-ledger.json',golden.evidence);
write('golden-version-registry.json',golden.versions);
write('golden-event-chain.json',golden.event_chain);
write('golden-lineage.json',golden.lineage_nodes);
write('golden-replay.json',replay,receiptDir);
write('CLP001Certification.json',cert,receiptDir);
console.log(JSON.stringify({correlation_id:golden.correlation_id,event_count:golden.events.length,evidence_count:golden.evidence.length,event_chain_root:cert.event_chain_root,replay_hash:cert.replay_hash,certification_hash:cert.certification_hash,status:cert.certification_status},null,2));
